public AccountID loadAccount(Map<String, String> accountProperties) {
  try {
    AccountID accountID = createAccount(accountProperties);
    loadAccount(accountID);
    return accountID;
  } catch (NullPointerException e) {
    // Handle the case where a required property is missing or null
    System.err.println("A required property is missing or null: " + e.getMessage());
    return null;
  } catch (RuntimeException e) {
    // Handle other runtime exceptions
    System.err.println("An unexpected error occurred: " + e.getMessage());
    return null;
  }
}
